-- Kino Lumen, Kleeberg: the two weeks from Monday 2 to Sunday 15 November 2026.
-- Generated by generate_data.py; built fresh for every query.
-- Times are text in the form 'YYYY-MM-DD HH:MM', so they compare and sort correctly.

CREATE TABLE halls (
  hall INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  seats INTEGER NOT NULL
);


CREATE TABLE screenings (
  screening_id INTEGER PRIMARY KEY,
  starts TEXT NOT NULL,
  hall INTEGER NOT NULL REFERENCES halls (hall),
  film TEXT NOT NULL
);


CREATE TABLE tickets (
  ticket_no INTEGER PRIMARY KEY,  -- printed on the ticket; each till has its own roll
  sold_at TEXT NOT NULL,
  screening_id INTEGER NOT NULL REFERENCES screenings (screening_id),
  till INTEGER NOT NULL,
  price REAL NOT NULL
);


CREATE TABLE tally (
  screening_id INTEGER PRIMARY KEY REFERENCES screenings (screening_id),
  admitted INTEGER NOT NULL  -- stubs Ben tore at the door
);


CREATE TABLE staff (
  staff_id INTEGER PRIMARY KEY,
  name TEXT NOT NULL,
  role TEXT NOT NULL
);


CREATE TABLE rota (
  day TEXT NOT NULL,  -- 'YYYY-MM-DD'
  shift TEXT NOT NULL,  -- 'afternoon' or 'evening'
  post TEXT NOT NULL,  -- 'till 1', 'till 2', 'snack bar', 'drinks bar' or 'door'
  staff_id INTEGER NOT NULL REFERENCES staff (staff_id),
  PRIMARY KEY (day, shift, post)
);


CREATE TABLE snack_sales (
  sale_id INTEGER PRIMARY KEY,
  sold_at TEXT NOT NULL,
  counter TEXT NOT NULL,  -- 'snack bar' or 'drinks bar'
  item TEXT NOT NULL,
  price REAL NOT NULL,
  staff_id INTEGER NOT NULL REFERENCES staff (staff_id)  -- signed in at that counter
);


CREATE TABLE clicks (
  click_id INTEGER PRIMARY KEY,
  time TEXT NOT NULL,  -- 'YYYY-MM-DD HH:MM:SS'
  delta INTEGER NOT NULL  -- +1 someone came in, -1 someone went out
);

